const body = $json.body || {};
const runId = /^[a-f0-9]{24}$/.test(String(body.runId ?? '')) ? String(body.runId) : '';
const runChain = Number.isInteger(body.runChain) && body.runChain >= 0 && body.runChain < 4 ? body.runChain : 0;

// Accept either a full Google Sheets URL or a raw sheet ID
function extractSheetId(input) {
  if (!input) return '';
  const match = String(input).match(/\/d\/([a-zA-Z0-9-_]+)/);
  return match ? match[1] : String(input).trim();
}

const sheetId = extractSheetId(body.sheetUrl || body.sheetId);
if (!sheetId) {
  throw new Error('No sheetUrl or sheetId provided in the webhook body, or the sheet URL could not be parsed.');
}

// Historical metrics date range — defaults to trailing 12 months if not supplied
const MONTHS = ["JANUARY","FEBRUARY","MARCH","APRIL","MAY","JUNE","JULY","AUGUST","SEPTEMBER","OCTOBER","NOVEMBER","DECEMBER"];
const now = new Date();
const endYear = body.endYear || now.getFullYear();
const endMonth = body.endMonth || MONTHS[now.getMonth()];
const startRef = new Date(now.getFullYear(), now.getMonth() - 11, 1);
const startYear = body.startYear || startRef.getFullYear();
const startMonth = body.startMonth || MONTHS[startRef.getMonth()];

// Location targeting — allLocations (default true) pulls every configured
// region; set it false and pass locations: ["Maharashtra", "Bengaluru", ...]
// (tabName values from the Code in JavaScript node) to run a subset only.
const allLocations = body.allLocations !== undefined ? !!body.allLocations : true;
const locations = Array.isArray(body.locations) ? body.locations : [];

// Minimum average monthly searches a keyword needs to be kept. Default 500;
// pass minVolume: 0 in the webhook body to keep every keyword (no volume floor).
const minVolume = body.minVolume !== undefined ? Number(body.minVolume) : 500;

// phase: 'ideas' = only collect keywords from the websites, 'states' = only fill
// the location tabs, 'all' (default) = both. Several 'states' runs can go in
// parallel as long as each one gets a different `locations` list.
const phase = ['ideas', 'states'].includes(String(body.phase)) ? String(body.phase) : 'all';

// Pause after every Google Ads historical-metrics call, per run (default 3s).
// Total request rate = parallel runs / (call time + waitSeconds).
const waitSeconds = body.waitSeconds !== undefined ? Math.max(0, Number(body.waitSeconds)) : 3;

// Most new websites one run will process (default 30). Websites already done are
// skipped, so run again to continue with the next ones. Keeps one run's data small.
const maxSites = body.maxSites !== undefined ? Math.max(1, Number(body.maxSites)) : 30;

// onlySites: ["reginaldmen.com"] = process just these websites (even if they were
// done before) and nothing else. Keywords already in the sheet are never added twice.
const onlySites = Array.isArray(body.onlySites) ? body.onlySites.map(String) : [];

return [{
  json: {
    sheetId,
    runId,
    runChain,
    allLocations,
    locations,
    minVolume,
    phase,
    waitSeconds,
    maxSites,
    onlySites,
    startYear,
    startMonth,
    endYear,
    endMonth
  }
}];

const MONTHS = ['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER'];

function monthYearLabel(m) {
  const idx = MONTHS.indexOf(String(m.month || '').toUpperCase());
  const name = idx >= 0 ? MONTHS[idx][0] + MONTHS[idx].slice(1).toLowerCase() : m.month;
  return name + ' ' + m.year;
}

function monthSortKey(m) {
  const idx = MONTHS.indexOf(String(m.month || '').toUpperCase());
  return (Number(m.year) || 0) * 100 + (idx >= 0 ? idx : 0);
}

// Google returns int64 values as strings; the sheet needs real numbers.
const num = v => (v === undefined || v === null || v === '' ? '' : Number(v));
const bid = v => (v === undefined || v === null || v === '' ? '' : Math.round(Number(v) / 10000) / 100); // micros -> currency units
const minVol = Number($('Config').first().json.minVolume ?? 500); // 0 = keep everything

// Always returns exactly one item (even with zero rows) so the state loop
// never stalls; failed batches are counted in apiErrors instead of vanishing.
const monthCols = new Map();
const rows = [];
let apiErrors = 0;

for (const item of $input.all()) {
  const j = item.json;
  if (j.error) { apiErrors++; continue; }
  for (const r of (Array.isArray(j.results) ? j.results : [])) {
    const m = r.keywordMetrics || {};
    if (Number(m.avgMonthlySearches ?? 0) < minVol) continue;
    const row = {
      Keyword: r.text,
      'search volume': num(m.avgMonthlySearches),
      'competition index': num(m.competitionIndex),
      'low bid': bid(m.lowTopOfPageBidMicros),
      'high bid': bid(m.highTopOfPageBidMicros),
      competition: m.competition
    };
    for (const mv of (m.monthlySearchVolumes || [])) {
      const label = monthYearLabel(mv);
      row[label] = num(mv.monthlySearches);
      monthCols.set(label, monthSortKey(mv));
    }
    rows.push(row);
  }
}

const sortedMonthCols = [...monthCols.entries()].sort((a, b) => a[1] - b[1]).map(e => e[0]);
const baseCols = ['Keyword', 'search volume', 'competition index', 'low bid', 'high bid', 'competition'];

return [{ json: { rows, desiredColumns: baseCols.concat(sortedMonthCols), apiErrors }, pairedItem: { item: 0 } }];

const plan = $input.first().json;
const existingItem = $('Get Existing Sheet Data').first();
const existing = (existingItem && existingItem.json.values) || [];
// Fix the old 'low big' typo in tabs that already have it.
const existingHeaders = (existing.length ? existing[0] : []).map(h => (h === 'low big' ? 'low bid' : h));
const existingRows = existing.slice(1);

const desiredColumns = plan.desiredColumns || [];
const rows = plan.rows || [];

// Keep whatever headers already exist in the sheet, and only append columns
// that are genuinely new (e.g. this month's label). Never drops a column.
const mergedHeaders = existingHeaders.slice();
for (const col of desiredColumns) {
  if (!mergedHeaders.includes(col)) mergedHeaders.push(col);
}

const keywordColIdx = mergedHeaders.indexOf('Keyword') >= 0 ? mergedHeaders.indexOf('Keyword') : 0;

const keywordRowIndex = new Map();
existingRows.forEach((r, i) => {
  const kw = (r[keywordColIdx] || '').toString().trim().toLowerCase();
  if (kw) keywordRowIndex.set(kw, i);
});

function colLetter(idx) {
  let n = idx + 1, s = '';
  while (n > 0) {
    const rem = (n - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

const tabName = $('Loop over states').first().json.tabName;
const updateRanges = [];
const appendRows = [];

for (const row of rows) {
  const kw = String(row.Keyword || '').trim().toLowerCase();
  if (!kw) continue;

  const existingIdx = keywordRowIndex.get(kw);
  if (existingIdx !== undefined && existingIdx >= 0) {
    // Existing keyword: rewrite its full row width so old columns that aren't
    // part of this run's data keep their stored values instead of going blank.
    const sheetRowNumber = existingIdx + 2;
    const existingRowValues = existingRows[existingIdx] || [];
    const fullRow = mergedHeaders.map((col, i) => {
      if (Object.prototype.hasOwnProperty.call(row, col)) return row[col] === undefined ? '' : row[col];
      return existingRowValues[i] === undefined ? '' : existingRowValues[i];
    });
    updateRanges.push({
      range: `'${tabName}'!A${sheetRowNumber}:${colLetter(mergedHeaders.length - 1)}${sheetRowNumber}`,
      values: [fullRow]
    });
    keywordRowIndex.set(kw, -1);
  } else if (existingIdx === undefined) {
    const fullRow = mergedHeaders.map(col => row[col] === undefined ? '' : row[col]);
    appendRows.push(fullRow);
    keywordRowIndex.set(kw, -1);
  }
}

return [{
  json: {
    tabName,
    mergedHeaders,
    updateRanges,
    appendRows,
    apiErrors: plan.apiErrors || 0
  },
  pairedItem: { item: 0 }
}];

const currentWebsite = $('Loop Over Items').item.json.website;
const inputItems = $input.all();
const norm = k => String(k ?? '').trim().toLowerCase();
const minVol = Number($('Config').first().json.minVolume ?? 500);

// Keywords already in the sheet, plus ones added earlier in this same run.
const sd = $getWorkflowStaticData('node');
if (sd.execId !== $execution.id) { sd.execId = $execution.id; sd.seen = {}; }
const existing = new Set(($('Aggregate Existing Keywords').first().json.data || []).map(r => norm(r.Keyword)).filter(Boolean));

// inputItems can be several pages of Google results; no cap on how many we keep.
const newItems = [];
for (let idx = 0; idx < inputItems.length; idx++) {
  const results = inputItems[idx].json.results || [];
  for (const result of results) {
    // Same volume floor as the Filter node (default 500, 0 = keep everything),
    // done here so we can tell "nothing usable for this URL" apart from "more to process".
    if (Number(result.keywordIdeaMetrics?.avgMonthlySearches ?? 0) < minVol) continue;
    const kw = norm(result.text);
    if (!kw || existing.has(kw) || sd.seen[kw]) continue;
    sd.seen[kw] = 1;
    result.Website = currentWebsite;
    newItems.push({ json: result, pairedItem: idx });
  }
}

// Nothing new (empty result, API error, all under the floor, or all duplicates): emit
// a marker so the loop still moves on to the next URL instead of stopping.
if (newItems.length === 0) {
  return [{ json: { _empty: true, Website: currentWebsite, error: inputItems[0]?.json?.error || null }, pairedItem: { item: 0 } }];
}

return newItems;

const BATCH_SIZE = 5000; // Google Ads allows at most 10,000 keywords per request
const { tabName, geoId } = $('Loop over states').item.json;
const norm = k => String(k ?? '').trim().toLowerCase();

const all = new Set(($('Aggregate').first().json.data || []).map(r => norm(r.Keyword)).filter(Boolean));

const existing = $input.first().json.values || [];
const header = existing[0] || [];
const kwIdx = header.indexOf('Keyword') >= 0 ? header.indexOf('Keyword') : 0;
const have = new Set(existing.slice(1).map(r => norm(r[kwIdx])).filter(Boolean));

// Only ask Google for keywords this tab does not have yet.
const missing = [...all].filter(k => !have.has(k));
if (!missing.length) return [{ json: { skip: true, tabName, geoId }, pairedItem: { item: 0 } }];

const out = [];
for (let i = 0; i < missing.length; i += BATCH_SIZE) {
  out.push({ json: { tabName, geoId, keywords: missing.slice(i, i + BATCH_SIZE) }, pairedItem: { item: 0 } });
}
return out;

const siteKey = u => String(u ?? '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '');
const cfg = $('Config').first().json;
const maxSites = Number(cfg.maxSites ?? 30);
const only = new Set((cfg.onlySites || []).map(siteKey).filter(Boolean));

// Websites that already produced keywords in the Keyword input tab are done: skip them.
const done = new Set(($('Aggregate Existing Keywords').first().json.data || []).map(r => siteKey(r.Website)).filter(Boolean));

const seen = new Set();
const out = [];
let total = 0;
$input.all().forEach((it, i) => {
  const raw = String(it.json.website ?? '').trim();
  if (!raw) return;
  total++;
  const key = siteKey(raw);
  if (seen.has(key)) return;
  // onlySites: take just those, ignoring the done check. Otherwise skip done ones.
  if (only.size) { if (!only.has(key)) return; }
  else if (done.has(key)) return;
  seen.add(key);
  // pairedItem keeps the link back to Config for the nodes further down.
  out.push({ json: { ...it.json, website: raw }, pairedItem: { item: i } });
});
if (!total) throw new Error('No websites found in the Website Input tab (blank rows are ignored).');

// Nothing to do: tell the next node, so the run still ends cleanly.
if (!out.length) return [{ json: { _allDone: true }, pairedItem: { item: 0 } }];

// Only take the next maxSites new websites; run again for the rest.
return only.size ? out : out.slice(0, maxSites);

// Collapse the existing Keyword input rows into one item, and keep the link to the
// earlier item so later nodes can still read $('Config').item.
const data = $input.all()
  .map(i => ({ Keyword: i.json.Keyword, Website: i.json.Website }))
  .filter(r => r.Keyword || r.Website);
return [{ json: { data }, pairedItem: { item: 0 } }];

// Google Sheets allows 20,000,000 cells per workbook. Each location tab needs about (keywords x 16 columns).
// Stop early with a clear message instead of failing halfway through a long run.
const cfg = $('Config').first().json;
const n = ($input.first().json.data || []).length;
const locs = cfg.allLocations ? 48 : (cfg.locations || []).length;
const COLS = 16;
const LIMIT = 17000000; // keep a safety margin under 20M
const perTab = Math.max(1, n * COLS);
const total = perTab * locs;
if (total > LIMIT) {
  const maxTabs = Math.max(1, Math.floor(LIMIT / perTab));
  throw new Error(`Too big for one Google Sheet: ${n} keywords x ${locs} location tabs is about ${total.toLocaleString()} cells (limit 20,000,000). Keep at most ${maxTabs} location tabs in one sheet: pass "allLocations": false and "locations": [...] for a smaller group, and use another sheet for the rest. Create location tabs with only 16 columns.`);
}
return $input.all().map((it, i) => ({ json: it.json, pairedItem: { item: i } }));

// Split the locations into groups of 6 tabs and run 4 chains in parallel.
// Each chain runs its groups one after the other, then runs them again once
// (second pass fills any keywords Google missed the first time).
const cfg = $('Config').first().json;
const tabs = $('Code in JavaScript').all().map(i => i.json.tabName);
const SIZE = 6, CHAINS = 4;
const groups = [];
for (let i = 0; i < tabs.length; i += SIZE) groups.push(tabs.slice(i, i + SIZE));
const chains = Array.from({ length: Math.min(CHAINS, groups.length) }, () => []);
groups.forEach((g, i) => chains[i % chains.length].push(g));
const base = {
  sheetUrl: `https://docs.google.com/spreadsheets/d/${cfg.sheetId}/edit`,
  phase: 'states', allLocations: false, minVolume: cfg.minVolume, waitSeconds: cfg.waitSeconds,
  startYear: cfg.startYear, startMonth: cfg.startMonth, endYear: cfg.endYear, endMonth: cfg.endMonth,
  isChild: true
};
return chains.map((runs, runChain) => {
  const seq = [...runs, ...runs];
  const [first, ...rest] = seq;
  return { json: { body: { ...base, locations: first, chain: rest, runId: cfg.runId, runChain } }, pairedItem: { item: 0 } };
});

// This run is part of a chain: start the next group of the chain.
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body || {};
const [next, ...rest] = body.chain || [];
return [{ json: { body: {
  sheetUrl: `https://docs.google.com/spreadsheets/d/${cfg.sheetId}/edit`,
  phase: 'states', allLocations: false, minVolume: cfg.minVolume, waitSeconds: cfg.waitSeconds,
  startYear: cfg.startYear, startMonth: cfg.startMonth, endYear: cfg.endYear, endMonth: cfg.endMonth,
  isChild: true, locations: next, chain: rest, runId: cfg.runId, runChain: cfg.runChain
} }, pairedItem: { item: 0 } }];
